window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["human-in-the-loop"]={"title":"人在回路：把稀缺的人类判断放到能改变风险的节点","subtitle":"从风险分层、升级阈值、审核界面和队列容量，到自动化偏见与反馈采样，设计真正降低伤害的人机闭环。","thesis":"人在回路不是“最后点确认”，而是把有资格的人、必要证据和可撤销决定放在正确时刻；若审核者无法发现错误或没有拒绝权，<b>人工步骤只增加延迟而不降低风险</b>。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"模型给退款请求0.8的正确概率","rule":"错误概率乘损失并加人工与延迟成本","steps":"22 元复核成本低于 92 元自动成本","interpretation":"不可把模型语气或 token 概率当任务正确率"}}],"formulas":[{"id":"hitl-expected-cost","section":3,"formulaIndex":1,"symbols":[{"name":"a","meaning":"候选处置动作以及其中期望成本最低的动作","evidence":"a 是候选动作"},{"name":"P","meaning":"给定案例和动作后的任务错误概率","evidence":"是采取动作后的错误概率"},{"name":"error","meaning":"采取动作后产生错误业务结果的事件","evidence":"错误概率乘损失"},{"name":"x","meaning":"当前需要路由或审核的业务案例","evidence":"x 是当前案例"},{"name":"C","meaning":"错误损失、人工复核或延迟中的一项成本","evidence":"三个 C 分别是错误损失、复核成本和延迟成本"}]},{"id":"hitl-queue-utilization","section":8,"formulaIndex":1,"symbols":[{"name":"ρ","meaning":"审核需求占理论处理能力的利用率","evidence":"ρ 是审核容量利用率"},{"name":"λ","meaning":"单位时间到达审核队列的任务数","evidence":"λ 是每小时到达任务数"},{"name":"c","meaning":"同时参与处理队列的审核者人数","evidence":"c 是审核者人数"},{"name":"μ","meaning":"单个审核者单位时间平均处理任务数","evidence":"μ 是单人每小时处理数"}]}],"termReviews":[{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"期望损失","meaning":"把各错误结果的概率与业务代价相乘后求和的决策成本","purpose":"在自动、复核和禁止之间按风险成本选择","definitionEvidence":"错误概率乘损失","purposeEvidence":"输出期望成本最低的自动、复核或禁止动作"}]},{"section":6,"reviewedAt":"2026-07-27","terms":[{"name":"锚定","meaning":"人的判断被先看到的模型建议过度影响的认知偏差","purpose":"解释审核者为何可能机械沿用模型结论","definitionEvidence":"减轻锚定","purposeEvidence":"先形成初判再显示模型建议"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"人在回路在风险决策点接入有资格且有拒绝权的人。","evidence":"人在回路是在特定决策点把有资格的人、原始证据和拒绝权接入自动系统"},"problem":{"answer":"它让人的判断能在伤害发生前改变结果。","evidence":"用人的判断改变风险结果"},"inputOutput":{"answer":"输入风险证据资格决定，输出批准修改拒绝或升级。","evidence":"输入是风险动作、审核者资格、证据和可用决定，输出是批准、修改、拒绝或升级"},"mechanism":{"answer":"把证据和可执行权交给正确时刻的合格人员。","evidence":"有资格的人、原始证据和拒绝权"},"interpretation":{"answer":"人工步骤有效需真正改变风险结果。","evidence":"人的判断能否改变结果"},"boundary":{"answer":"无证据权力的确认只增加延迟和依赖。","evidence":"会增加延迟并形成自动化依赖"}},{"section":2,"definition":{"answer":"事前批准同步复核事后抽检离线纠错是四类介入点。","evidence":"输出事前批准、同步复核、事后抽检或离线纠错"},"problem":{"answer":"它区分四种人工参与分别保护什么。","evidence":"四种介入点解决不同问题"},"inputOutput":{"answer":"输入可逆性伤害时机目标，输出介入方式。","evidence":"输入动作可逆性、伤害时机和改进目标，输出事前批准、同步复核、事后抽检或离线纠错"},"mechanism":{"answer":"按是否保护当前动作结果未知错误或未来模型选择。","evidence":"分别保护当前副作用、交付结果、未知错误和未来模型"},"interpretation":{"answer":"四种方式可以组合但不能互相替代。","evidence":"可以组合但不能互相替代"},"boundary":{"answer":"事后标注不能撤销已经发生的伤害。","evidence":"无法撤销已经发生的伤害"}},{"section":3,"definition":{"answer":"退款案例用期望损失选择自动复核或禁止。","evidence":"输出期望成本最低的自动、复核或禁止动作"},"problem":{"answer":"它解决正确概率零点八是否应自动批准。","evidence":"是否应该自动批准"},"inputOutput":{"answer":"输入概率和各类成本，输出最低成本动作。","evidence":"输入校准正确概率、错误退款损失、自动收益、复核成本和延迟损失，输出期望成本最低的自动、复核或禁止动作"},"mechanism":{"answer":"逐动作计算错误概率乘损失并加人工延迟成本。","evidence":"错误概率乘损失并加人工与延迟成本"},"interpretation":{"answer":"本例复核二十二元低于自动九十二元。","evidence":"22 元复核成本低于 92 元自动成本"},"boundary":{"answer":"结论依赖校准和成本，token 概率不能替代。","evidence":"不可把模型语气或 token 概率当任务正确率"}},{"section":4,"definition":{"answer":"风险路由组合红线规则校准阈值和随机抽检。","evidence":"输出自动、人工、禁止以及随机抽检分配"},"problem":{"answer":"它防止只送低置信样本漏掉高置信系统错误。","evidence":"只把低置信样本交给人，会漏掉什么"},"inputOutput":{"answer":"输入规则分数容量流量，输出路由和抽检。","evidence":"输入红线规则、校准不确定性、审核容量和生产流量，输出自动、人工、禁止以及随机抽检分配"},"mechanism":{"answer":"红线阻断，高风险升级，不确定按分数，自动流随机抽检。","evidence":"自动流量保留抽检"},"interpretation":{"answer":"随机抽检用于估计阈值未发现的错误。","evidence":"估计真正漏审率"},"boundary":{"answer":"拥堵不能静默取消高风险红线。","evidence":"不能静默取消高风险红线"}},{"section":5,"definition":{"answer":"决策门按风险把建议路由到自动人工或禁止。","evidence":"输出低风险自动、合格复核或禁止延迟路径"},"problem":{"answer":"它让自动人工禁止共享同一风险模型。","evidence":"怎样让自动化、人工复核和禁止执行共享同一风险模型"},"inputOutput":{"answer":"输入建议证据成本容量，输出三类处置路径。","evidence":"输入 AI 建议、证据、错误成本、可逆性、校准和容量，输出低风险自动、合格复核或禁止延迟路径"},"mechanism":{"answer":"风险路由在副作用前选择并用结果反馈更新。","evidence":"风险路由器在副作用前选择动作"},"interpretation":{"answer":"路由人工只表示该案例需要判断。","evidence":"路由到人工只表示需要判断"},"boundary":{"answer":"它不表示人必然正确或容量足够。","evidence":"不表示审核者必然正确或当前容量足够"}},{"section":6,"definition":{"answer":"审核界面帮助人独立检查模型建议与原始证据。","evidence":"审核界面必须帮助人发现模型错误"},"problem":{"answer":"它避免只展示结论和同意拒绝造成锚定。","evidence":"审核者能做出独立判断吗"},"inputOutput":{"answer":"输入材料建议证据后果，输出批准修改或拒绝。","evidence":"输入原始材料、模型建议、证据、现状差异、后果和替代方案，输出审核者可独立作出的批准修改或拒绝"},"mechanism":{"answer":"高风险先初判再显示建议，三类决定同样可用。","evidence":"先形成初判再显示模型建议"},"interpretation":{"answer":"记录理由用于重建当时审核条件。","evidence":"记录审核者、时间、看到的模型/规则版本和理由"},"boundary":{"answer":"默认焦点和追责压力不能诱导机械同意。","evidence":"不能用默认焦点或追责压力诱导机械同意"}},{"section":7,"definition":{"answer":"人因评测衡量盲审基线自动化偏见分歧和疲劳。","evidence":"输出基线正确率、自动化偏见、分歧和疲劳指标"},"problem":{"answer":"它区分专家分歧来自人错误还是案例含糊。","evidence":"是人不可靠还是案例本来模糊"},"inputOutput":{"answer":"输入盲审对照难度轮班速度，输出人因指标。","evidence":"输入盲审样本、含已知错误建议的对照、案例难度、轮班和审核速度，输出基线正确率、自动化偏见、分歧和疲劳指标"},"mechanism":{"answer":"先测无模型判断再比较建议造成的改判。","evidence":"先测不看模型的判断"},"interpretation":{"answer":"分歧可能反映任务和指南含糊。","evidence":"专家分歧可能来自任务含糊"},"boundary":{"answer":"不能只用一致率断言人不可靠。","evidence":"不能只用一致率断言人不可靠"}},{"section":8,"definition":{"answer":"审核队列容量用到达率人数和服务率描述负载。","evidence":"审核队列容量输入到达率"},"problem":{"answer":"它判断需求超过处理率时风险策略能否工作。","evidence":"审核到达率超过处理率时，风险策略还能工作吗"},"inputOutput":{"answer":"输入到达人员服务风险 SLA，输出利用率和降级。","evidence":"输入到达率、审核人数、单人服务率、风险等级和 SLA，输出利用率、队龄、所需人员和降级动作"},"mechanism":{"answer":"计算利用率并按峰值复杂度保留余量。","evidence":"利用率接近一时等待非线性增长"},"interpretation":{"answer":"八人只达到理论满载而没有峰值余量。","evidence":"八人只达到理论满载而无峰值余量"},"boundary":{"answer":"平均公式不能替代分布休息和故障演练。","evidence":"不替代复杂度分布、休息和故障演练"}},{"section":9,"definition":{"answer":"反馈治理校正人工升级数据的选择偏差。","evidence":"反馈数据带选择偏差"},"problem":{"answer":"它防止只用困难升级样本训练而偏离生产。","evidence":"只用“被升级给人”的困难样本训练"},"inputOutput":{"answer":"输入升级路由采样随机标签，输出可校正训练集。","evidence":"输入升级样本、路由原因、采样概率、自动流量随机标签和审核分歧，输出可校正选择偏差的训练集"},"mechanism":{"answer":"保存采样概率并抽标自动流量，独立测试。","evidence":"用独立近生产测试集评估"},"interpretation":{"answer":"升级集不是生产总体分布。","evidence":"升级集不是生产分布"},"boundary":{"answer":"重加权不能消除未抽样的未知偏差。","evidence":"不能消除未被抽样的未知偏差"}},{"section":10,"definition":{"answer":"闭环评测比较多种路由方案对最终伤害的影响。","evidence":"输出漏审、误升级、改判、最终伤害、队列、申诉和成本"},"problem":{"answer":"它证明人工是否真正减少最终伤害。","evidence":"评测必须证明人工真的减少最终伤害"},"inputOutput":{"answer":"输入四类方案，输出风险队列申诉成本。","evidence":"输入全自动、规则路由、不确定性路由和人机组合方案，输出漏审、误升级、改判、最终伤害、队列、申诉和成本"},"mechanism":{"answer":"按风险切片并随机抽查自动通过流量。","evidence":"抽查自动通过流量估计沉在水下的高置信错误"},"interpretation":{"answer":"自动化率高只表示人处理更少。","evidence":"自动化率高只表示人处理更少"},"boundary":{"answer":"它不能证明最终风险更低。","evidence":"不能证明最终风险更低"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分批准、复核、抽检与标注；用错误成本推导升级策略；设计能抵抗自动化偏见的审核界面；评测漏审、队列与反馈偏差。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>先问人的判断能否改变结果<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">每次都让人点“确认”，为什么可能比全自动更危险？</p><p>重复低价值确认会形成习惯点击，真正高风险案例反而得不到注意。有效的人在回路要明确：谁具备领域资格、在动作前还是动作后介入、看到哪些原始证据、能批准/修改/拒绝什么、决定由谁负责。人工不是模型之外的神奇真值源，也会疲劳、偏见和犯错。</p><p>人在回路是在特定决策点把有资格的人、原始证据和拒绝权接入自动系统。输入是风险动作、审核者资格、证据和可用决定，输出是批准、修改、拒绝或升级。它用人的判断改变风险结果；只增加确认点击而不给证据和权力，会增加延迟并形成自动化依赖。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>四种介入点解决不同问题<span class=\"dd-badge eng\">控制设计</span></h2><p class=\"dd-lead\">事前批准、事后抽检和标注反馈可以互相替代吗？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方式</th><th>时机</th><th>适用</th><th>局限</th></tr></thead><tbody><tr><td>事前批准</td><td>副作用发生前</td><td>付款、发布、删除</td><td>增加关键路径延迟</td></tr><tr><td>同步复核</td><td>结果交付前</td><td>医疗/金融建议</td><td>需要持续容量</td></tr><tr><td>事后抽检</td><td>低风险动作后</td><td>发现漂移与未知错</td><td>不能撤回即时伤害</td></tr><tr><td>标注/纠错</td><td>离线</td><td>改进规则和模型</td><td>不保护当前案例</td></tr></tbody></table></div><p>介入点选择输入动作可逆性、伤害时机和改进目标，输出事前批准、同步复核、事后抽检或离线纠错。四种方式分别保护当前副作用、交付结果、未知错误和未来模型。它们可以组合但不能互相替代，事后标注无法撤销已经发生的伤害。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：用期望损失决定自动、复核还是禁止<span class=\"dd-badge math\">案例推演</span></h2><p class=\"dd-lead\">模型给退款请求0.8的正确概率，是否应该自动批准？</p><p>设错误退款损失500元，正确自动处理收益（节省人工）8元；人工复核成本12元，复核后错误概率降至2%。自动处理期望损失为 (1−0.8)×500−8=<b>92元</b>；人工复核期望损失为12+0.02×500=<b>22元</b>，因此应复核。若拒绝/延迟损失为30元，且没有合格审核容量，则宁可延迟也不自动放行。</p><div class=\"dd-formula\" data-formula-id=\"hitl-expected-cost\" data-display=\"mathml\"><math display=\"block\" aria-label=\"最优动作 a 星是在所有动作中选择错误期望损失、复核成本与延迟成本之和最小者\"><msup><mi>a</mi><mo>*</mo></msup><mo>=</mo><munder><mi>argmin</mi><mi>a</mi></munder><mo>[</mo><mi>P</mi><mo>(</mo><mi>error</mi><mo>|</mo><mi>x</mi><mo>,</mo><mi>a</mi><mo>)</mo><msub><mi>C</mi><mtext>error</mtext></msub><mo>+</mo><msub><mi>C</mi><mtext>review</mtext></msub><mo>+</mo><msub><mi>C</mi><mtext>delay</mtext></msub><mo>]</mo></math></div><p class=\"dd-formula-note\"><code>a*</code> 是期望成本最低的动作，<code>a</code> 是候选动作，<code>x</code> 是当前案例，<code>P(error|x,a)</code> 是采取动作后的错误概率；三个 <code>C</code> 分别是错误损失、复核成本和延迟成本。</p><p>这里的0.8必须来自任务级校准，不是模型语气或单token概率。不同金额、客户、地区与可逆性应使用不同成本和阈值。</p><p>退款案例输入校准正确概率、错误退款损失、自动收益、复核成本和延迟损失，输出期望成本最低的自动、复核或禁止动作。逐动作计算错误概率乘损失并加人工与延迟成本；本例 22 元复核成本低于 92 元自动成本。结论依赖校准和业务成本，不可把模型语气或 token 概率当任务正确率。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>风险分层需要红线、阈值与随机抽检<span class=\"dd-badge eng\">路由</span></h2><p class=\"dd-lead\">只把低置信样本交给人，会漏掉什么？</p><p>系统性错误可能高置信，未知新模式也不会主动触发阈值。因此策略通常组合：不可逆/受监管动作无条件人工或禁止；已知高风险按规则升级；不确定样本按校准分数升级；自动通过流量中保留随机和分层抽检，用来估计真正漏审率。</p><p>阈值随错误成本、审核容量和分布变化调整，但红线不能在队列拥堵时静默取消。</p><p>风险路由输入红线规则、校准不确定性、审核容量和生产流量，输出自动、人工、禁止以及随机抽检分配。红线无条件阻断，已知高风险按规则升级，不确定样本按分数升级，自动流量保留抽检。队列拥堵可以延迟低风险服务，但不能静默取消高风险红线。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：人的价值在决策门，不在流程末尾盖章<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">怎样让自动化、人工复核和禁止执行共享同一风险模型？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 320\" role=\"img\" aria-label=\"AI建议和证据经过风险校准后路由到自动执行人工复核或禁止并由结果反馈监控\"><defs><marker id=\"h27a\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"18\" y=\"112\" width=\"120\" height=\"80\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"78\" y=\"140\" text-anchor=\"middle\" class=\"svg-t\">AI 建议</text><text x=\"78\" y=\"164\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">输入 · 证据 · 置信</text><text x=\"78\" y=\"183\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">拟执行差异</text><path d=\"M138,152 L195,152\" stroke=\"#788293\" marker-end=\"url(#h27a)\"/><rect x=\"200\" y=\"92\" width=\"155\" height=\"120\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"277\" y=\"122\" text-anchor=\"middle\" class=\"svg-t\">风险路由器</text><text x=\"277\" y=\"148\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">错误成本 · 可逆性</text><text x=\"277\" y=\"171\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">校准 · 规则 · 容量</text><text x=\"277\" y=\"194\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">红线不可降级</text><path d=\"M355,152 L415,68\" stroke=\"#788293\" marker-end=\"url(#h27a)\"/><path d=\"M355,152 L415,152\" stroke=\"#788293\" marker-end=\"url(#h27a)\"/><path d=\"M355,152 L415,236\" stroke=\"#788293\" marker-end=\"url(#h27a)\"/><rect x=\"420\" y=\"35\" width=\"155\" height=\"65\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"497\" y=\"62\" text-anchor=\"middle\" class=\"svg-t\">低风险自动</text><text x=\"497\" y=\"84\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">可回滚 + 随机抽检</text><rect x=\"420\" y=\"120\" width=\"155\" height=\"65\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"497\" y=\"147\" text-anchor=\"middle\" class=\"svg-t\">合格人员复核</text><text x=\"497\" y=\"169\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">批准 / 修改 / 拒绝</text><rect x=\"420\" y=\"205\" width=\"155\" height=\"65\" rx=\"9\" fill=\"#21252d\" stroke=\"#cf7c72\"/><text x=\"497\" y=\"232\" text-anchor=\"middle\" class=\"svg-t\">禁止 / 延迟</text><text x=\"497\" y=\"254\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">无容量也不越红线</text><path d=\"M575,68 L638,122\" stroke=\"#788293\" marker-end=\"url(#h27a)\"/><path d=\"M575,152 L638,152\" stroke=\"#788293\" marker-end=\"url(#h27a)\"/><path d=\"M575,237 L638,182\" stroke=\"#788293\" marker-end=\"url(#h27a)\"/><rect x=\"643\" y=\"105\" width=\"74\" height=\"95\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"680\" y=\"135\" text-anchor=\"middle\" class=\"svg-t\">结果</text><text x=\"680\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">伤害</text><text x=\"680\" y=\"179\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">反馈</text><path d=\"M680,200 C680,298 277,298 277,212\" fill=\"none\" stroke=\"#788293\" stroke-dasharray=\"6 5\" marker-end=\"url(#h27a)\"/></svg><figcaption>图 1　人工是风险路由的一种动作；容量不足时必须走显式降级，而不是绕过红线。</figcaption></figure><p>决策门图输入 AI 建议、证据、错误成本、可逆性、校准和容量，输出低风险自动、合格复核或禁止延迟路径。风险路由器在副作用前选择动作，结果与伤害反馈更新策略。路由到人工只表示需要判断，不表示审核者必然正确或当前容量足够。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>审核界面必须帮助人发现模型错误<span class=\"dd-badge eng\">交互</span></h2><p class=\"dd-lead\">只展示模型结论和“同意/拒绝”，审核者能做出独立判断吗？</p><p>界面展示原始输入、模型建议、来源证据、与现状的差异、可预见后果和替代方案；高风险场景可先让审核者形成初步判断，再显示模型建议，减轻锚定。拒绝和修改要与批准同样容易，默认焦点不能落在“确认”。</p><p>记录审核者、时间、看到的模型/规则版本和理由，但避免用追责恐惧逼迫机械保守。对领域资格、利益冲突和双人复核需求做明确约束。</p><p>审核界面输入原始材料、模型建议、证据、现状差异、后果和替代方案，输出审核者可独立作出的批准修改或拒绝。高风险时先形成初判再显示模型建议，拒绝与批准同样容易。记录理由支持审计，但界面不能用默认焦点或追责压力诱导机械同意。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>自动化偏见、疲劳与一致性都可测量<span class=\"dd-badge eng\">人因</span></h2><p class=\"dd-lead\">两位专家意见不同，是人不可靠还是案例本来模糊？</p><p>用盲审样本测不看模型时的基线，再比较看模型后的改判方向；插入已知错误建议测自动化偏见。审核一致性应结合案例难度、指南清晰度和最终伤害，不追求所有人机械一致。轮班长度、每小时案例数、界面复杂度与错误率一起监控。</p><p>定期校准会议处理分歧并更新指南；高影响争议应有升级和申诉渠道，而不是简单多数票。</p><p>人因评测输入盲审样本、含已知错误建议的对照、案例难度、轮班和审核速度，输出基线正确率、自动化偏见、分歧和疲劳指标。先测不看模型的判断，再比较模型建议造成的改判。专家分歧可能来自任务含糊，不能只用一致率断言人不可靠。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>队列是可靠性组件，不是运营细节<span class=\"dd-badge math\">容量</span></h2><p class=\"dd-lead\">审核到达率超过处理率时，风险策略还能工作吗？</p><p>若每小时到达120件、单人每小时处理15件，至少需要8个审核者才只达到100%利用率；实际还需为峰值、休息与复杂案例留余量。接近满载时等待时间会非线性增长。</p><div class=\"dd-formula\" data-formula-id=\"hitl-queue-utilization\" data-display=\"mathml\"><math display=\"block\" aria-label=\"审核队列利用率 rho 等于到达率 lambda 除以审核者数量 c 乘单人服务率 mu\"><mi>ρ</mi><mo>=</mo><mfrac><mi>λ</mi><mrow><mi>c</mi><mi>μ</mi></mrow></mfrac></math></div><p class=\"dd-formula-note\"><code>ρ</code> 是审核容量利用率，<code>λ</code> 是每小时到达任务数，<code>c</code> 是审核者人数，<code>μ</code> 是单人每小时处理数；ρ 接近 1 表示平均需求接近理论满载。</p><p>监控分风险等级的队龄与SLA；拥堵时低风险可延迟或暂停服务，高风险红线仍不得自动放行。必须演练审核系统不可用、节假日峰值和大规模模型漂移同时发生的情形。</p><p>审核队列容量输入到达率、审核人数、单人服务率、风险等级和 SLA，输出利用率、队龄、所需人员和降级动作。利用率接近一时等待非线性增长，因此八人只达到理论满载而无峰值余量。公式是平均容量近似，不替代复杂度分布、休息和故障演练。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>反馈数据带选择偏差，不能直接代表生产分布<span class=\"dd-badge eng\">学习闭环</span></h2><p class=\"dd-lead\">只用“被升级给人”的困难样本训练，模型会学到什么？</p><p>升级集由旧模型与规则选择，困难样本过多、自动通过样本缺少标签。直接训练会改变校准并可能过拟合少数审核者风格。保存采样概率和路由原因，对自动流量做随机标注；训练前去标识、质检、处理审核分歧，并用独立、接近生产分布的测试集评估。</p><p>反馈治理输入升级样本、路由原因、采样概率、自动流量随机标签和审核分歧，输出可校正选择偏差的训练集。升级集不是生产分布，训练前需去标识、质检并用独立近生产测试集评估。保存采样概率支持重加权，但不能消除未被抽样的未知偏差。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">10</span>评测必须证明人工真的减少最终伤害<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">自动化率提高，是否说明系统更成功？</p><p>同时报告高风险漏审率、误升级率、审核改判率、最终错误/伤害、处理时间、队列P95、审核一致性、申诉推翻率和成本。比较全自动、规则路由、模型不确定性路由与人机组合，并按金额、群体、审核者、时间和模型版本切片。</p><p>事后抽查自动通过样本是估计漏审分母的关键；没有它，只能看到被模型挑出来的问题，无法知道多少高置信错误沉在水下。</p><p>闭环评测输入全自动、规则路由、不确定性路由和人机组合方案，输出漏审、误升级、改判、最终伤害、队列、申诉和成本。按风险切片并抽查自动通过流量估计沉在水下的高置信错误。自动化率高只表示人处理更少，不能证明最终风险更低。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">11</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">人类参与不是安全证明，而是一项需要设计、容量和评测的控制。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>加确认按钮就有人在回路</td><td>人必须有证据、资格和改变结果的权力</td></tr><tr><td>只升级低置信样本</td><td>需红线规则与自动流量随机抽检</td></tr><tr><td>人一定比模型准</td><td>疲劳、锚定和知识不足同样会失败</td></tr><tr><td>反馈标签天然无偏</td><td>路由策略决定了人看到哪些样本</td></tr><tr><td>队列拥堵时可临时自动放行</td><td>高风险红线应转为延迟或停服</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>校准、决策成本、权限与审计</td></tr><tr><td><b>本页核心</b></td><td>介入点、风险路由、审核UI、容量</td></tr><tr><td>相邻</td><td>护栏、Agent身份、主动学习</td></tr><tr><td>治理</td><td>资格、责任、申诉、隐私与劳动条件</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">12</span>先澄清：人在回路、人工兜底与人类反馈不是一回事<span class=\"dd-badge intuition\">概念消歧</span></h2><p class=\"dd-lead\">客服最终可以接管，是否说明每个自动决策都有人监督？</p><p>人在回路强调某个决策路径中预先设计的人类控制点；人工兜底是系统失败后可转交给人；人类反馈是收集标签或偏好用于未来改进。三者时机、责任和保护对象不同。事后反馈不能撤销已经发生的支付或医疗伤害，提供客服电话也不等于动作前获得批准。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>把“有人参与过”当成安全证明。必须具体说明谁在何时看到什么、能阻止什么，以及无人可用时系统怎样降级。</div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">13</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>识别不可接受伤害与可逆性</li><li>为每类动作定义责任人和红线</li><li>校准风险并估计错误成本</li><li>路由到自动/复核/禁止</li><li>向审核者展示原始证据与差异</li><li>记录决定、理由和版本</li><li>抽检自动流量并监控队列</li><li>用无偏反馈修正规则和模型</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">14</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么确认按钮不等于有效人工控制？</li><li>只升级低置信样本会漏什么？</li><li>审核容量不足时高风险动作怎么办？</li><li>人工反馈为什么有选择偏差？</li><li>怎样证明人机闭环有效？</li><li>假设“人在回路：把稀缺的人类判断放到能改变风险的节点”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>若人没有证据、资格、时间或拒绝权，点击无法降低风险。</li><li>高置信系统性错误和未知新模式，需要红线规则与随机抽检。</li><li>延迟、拒绝或停服，不能绕过既定红线自动放行。</li><li>旧模型和路由规则决定了哪些样本被送审。</li><li>比较最终伤害、漏审、误升级、队列、成本与无人工/不同路由基线。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://www.nist.gov/itl/ai-risk-management-framework\" target=\"_blank\" rel=\"noopener\">NIST AI Risk Management Framework</a>：风险治理与人类监督</li><li><a href=\"https://doi.org/10.1145/3290605.3300233\" target=\"_blank\" rel=\"noopener\">Guidelines for Human-AI Interaction</a>：人机交互设计准则</li><li><a href=\"https://arxiv.org/abs/1606.06565\" target=\"_blank\" rel=\"noopener\">Concrete Problems in AI Safety</a>：人类监督、可扩展控制与安全问题</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
